      let chart = null;
      const renderChart = () => {
        if (!chart) {
          chart = echarts.init(card.querySelector(".chart"));
          chart.setOption(option);
          window.addEventListener("resize", () => chart?.resize());
        } else {
          chart.resize();
        }
      };
